public static TFMTranslations Find(LabelString _labelString, boolean _select4Update = false)
{
    TFMTranslations translation;

    translation.selectForUpdate(_select4Update);

    select firstonly translation where translation.LabelString == _labelString;

    if (!translation)
    {
        translation.LabelId = _labelString;
        translation.LabelString = _labelString;
    }

    return translation;
}

public static TFMTranslations FindByLabelId(LabelId _labelId, boolean _select4Update = false)
{
    TFMTranslations translation;

    translation.selectForUpdate(_select4Update);

    select firstonly translation where translation.LabelId == _labelId;

    return translation;
}

public static str GetTranslatedValue(LabelId _labelId, LanguageId _languageId)
{
    TFMTranslationLines translationLine;
    Label label;
    TFMTranslations translation;
    str translatedValue;

    if(!_labelId)
    {
        return '';
    }

    label = new Label(_languageId);

    if(strScan(_labelId, '@', 0, 1) > 0) 
    {
        translatedValue = label.extractString(_labelId);
        if(translatedValue)
        {
            return translatedValue;
        }
    }

    translation = TFMTranslations::FindByLabelId(_labelId);

    if(translation && translation.RecId)
    {
        // always start to see if there is a user defined translation with a value
        translationLine = TFMTranslationLines::find(translation.RecId, _languageId);

        // if there is a LabelString then it is a id from a label file
        translatedValue = (translationLine.RecId) ? translationLine.Translation : label.extractString(translation.LabelString);
    } 

    if(!translatedValue)
    {
        translatedValue = _labelId;
    }

    return translatedValue;
}

/// <summary>
/// Creates a translation header and returns the record.
/// </summary>
/// <param name = "_labelString"></param>
/// <param name = "_labelID"></param>
/// <returns></returns>
public static TFMTranslations create(LabelId _labelID, LabelString _labelString)
{
    TFMTranslations translation;
    LabelId _labelIdStripped = strReplace(_labelID, '@', '');

    if(_labelString)
    {
        translation.LabelString = _labelString; // the labelId in the lookup is the labelString
        translation.LabelId = _labelIdStripped;
    } 
    else
    {
        translation.LabelString = '';
        translation.LabelId = _labelIdStripped;
    }

    translation.insert();
    return translation;
}

public display LabelString LabelTranslated()
{
    str labelTranslated;
    TFMTranslationLines lines; 

    if(this.LabelString) // if the labelString is not empty
    {
        labelTranslated = SysLabel::isLabelId(this.LabelString) ? SysLabel::labelId2String(this.LabelString,new xInfo().language()) : this.LabelID;
    } 
    else
    {
        lines = TFMTranslationLines::find(this.RecId, currentUserLanguage());
        labelTranslated = lines.Translation;
    }

    return labelTranslated;
}

public display LabelString IdDisplay()
{
    str diplayValue;

    if(this.LabelString)
    {
        diplayValue = "@TFM:LabelId" + this.LabelString;
    } 
    else
    {
        diplayValue = this.LabelId;
    }

    return diplayValue;
}

/// <summary>
/// Resets the translations provider when writing to the table.
/// </summary>
public void write()
{
    super();
    TFMTranslationProvider::resetProvider();
}

/// <summary>
/// Inserts makes sure that there is a label Id in case there is a label String.
/// </summary>
public void insert()
{
    if(!this.LabelId)
    {
        this.LabelId = this.LabelString;
    }
    super();
    TFMTranslationProvider::resetProvider();
}
